INSERT INTO `item` (`id_item`, `id_orden`, `id_producto`, `id_tipo`, `cantidad`, `descripcion`) VALUES
(1, 46, 82, 1, 52, 'Quod melius sit, accedere? Statue contra aliquem confectum tantis animi corporisque doloribus, quanti in hominem maximi cadere possunt, nulla spe proposita fore levius aliquando, nulla praeterea neque praesenti nec expectata voluptate, quid eo miserius di'),
(2, 10, 12, 2, 39, 'Constituto veri a falso distinctio traditur. Restat locus huic disputationi vel maxime necessarius de amicitia, quam, si voluptas esset bonum, fuisse desideraturam. Idcirco enim non desideraret, quia, quod.'),
(3, 77, 59, 2, 61, 'Oriantur et intereant cotidie. Quae etsi mihi nullo modo probantur, tamen Democritum laudatum a ceteris ab hoc, qui eum unum secutus esset, nollem vituperatum. Iam in altera philosophiae parte. Quae.'),
(4, 66, 11, 1, 21, 'Satis esse, quid bonum sit aut quid malum, sensu iudicari, sed animo etiam ac ratione intellegi posse et voluptatem ipsam per se ipsam optabilem, sed quia consequuntur magni dolores eos, qui ratione voluptatem sequi nesciunt, neque porro quisquam est, qui'),
(5, 97, 27, 1, 94, 'Esset bonum, desideraret.\' -- Ita credo. -- \'Non est igitur voluptas bonum.\' Hoc ne statuam quidem dicturam pater aiebat, si loqui posset. Conclusum est enim in vita tantopere.'),
(6, 88, 20, 2, 59, 'Quam ut ipse loquerer, tum Triarius leniter arridens: Tu quidem, inquit, totum Epicurum paene e philosophorum choro sustulisti. Quid ei reliquisti, nisi te, quoquo.'),
(7, 20, 52, 1, 6, 'Recta et honesta quae sint, ea facere ipsa per se ipsam causam non multo maiores esse et voluptates repudiandae sint et molestiae non recusandae. Itaque earum rerum defuturum, quas natura non depravata desiderat. Et quem ad me de virtute misisti.'),
(8, 98, 78, 2, 17, 'Molestia perfruique maximis et animi et corporis voluptatibus, videtisne quam nihil molestiae consequatur, vel illum, qui dolorem ipsum, quia dolor sit, amet, consectetur, adipisci.'),
(9, 47, 73, 1, 89, 'Scribentur fortasse plura, si vita suppetet; et tamen, qui diligenter haec, quae de philosophia.'),
(10, 6, 68, 2, 87, 'Dixi, ad lineam, hunc naturalem esse omnium corporum motum. Deinde ibidem homo acutus, cum illud ocurreret, si omnia deorsus e regione ferrentur et, ut modo docui, cognitionis regula et iudicio ab eadem.'),
(11, 7, 7, 1, 62, 'Esse maius amicitia, nihil uberius, nihil iucundius. Nec vero quisquam stultus non horum morborum aliquo laborat, nemo igitur est non miser. Accedit etiam mors, quae quasi titillaret.'),
(12, 90, 47, 2, 22, 'Torquatis.\' Numquam hoc ita defendit Epicurus neque Metrodorus aut quisquam eorum, qui aut saperet aliquid aut ista didicisset. Et quod quaeritur saepe, cur tam.'),
(13, 54, 8, 1, 8, 'Etiam, et ii quidem eruditi Graecis litteris, contemnentes Latinas, qui se dicant in Graecis legendis operam malle consumere. Postremo aliquos futuros suspicor, qui me ad alias litteras vocent, genus hoc scribendi, etsi sit.'),
(14, 86, 26, 2, 40, 'Sed quia iucunditatis vel plurimum afferat. Nam diligi et carum esse iucundum est propterea, quia tutiorem vitam et voluptatem pleniorem efficit.'),
(15, 40, 38, 2, 17, 'Esse per se esse expetendam et insipientiam propter molestias esse fugiendam? Eademque ratione ne temperantiam quidem propter se esse expetendam et dolorem ipsum per se esse expetendam et insipientiam propter molestias esse fugiendam? Eademque ratione ne '),
(16, 55, 87, 1, 32, 'Tempus aut in voluptate ponatur, sed sine hoc institutionem omnino amicitiae non posse reperiri. Quapropter si ea, quae dices, libenter assentiar.'),
(17, 68, 6, 1, 28, 'Omni dolore detracto, nam quoniam, cum privamur dolore, ipsa liberatione et vacuitate omnis molestiae gaudemus, omne autem id, quo gaudemus, voluptas est, ut omne.'),
(18, 95, 39, 2, 5, 'Ultima antiquitate repetitis tria vix amicorum paria reperiuntur, ut ad id omnia referri oporteat, ipsum autem nusquam. Hoc Epicurus in voluptate ponatur, sed sine hoc institutionem omnino amicitiae non modo non inopem, ut vulgo putarent, sed locupletiore'),
(19, 5, 3, 1, 61, 'Recte, Chrysippe, concessum est nihil desiderare manum, cum ita esset affecta, secundum non recte, si voluptas summum sit bonum, affirmatis nullam omnino fore. De qua omne certamen est? Tuo vero id quidem, inquam, arbitratu. Sic faciam igitur, inquit: una'),
(20, 82, 77, 2, 21, 'Pendet ex futuris, sed expectat illa, fruitur praesentibus ab iisque M. Brutus dissentiet -- quod Graeci telos nominant --, quod ipsum nullam ad aliam rem, ad id omnia referri oporteat, ipsum autem nusquam. Hoc Epicurus in voluptate ponit, quod summum bon'),
(21, 16, 62, 1, 52, 'Sapiens solum amputata circumcisaque inanitate omni et errore naturae finibus contentus sine aegritudine possit et sine metu vivere. Quae est.'),
(22, 18, 92, 2, 39, 'Detraxit hosti. -- Et quidem se texit, ne interiret. -- At magnum periculum adiit. -- In oculis quidem exercitus. -- Quid ex eo est consecutus? -- Laudem et caritatem, quae sunt vitae sine metu degendae praesidia firmissima. -- Filium morte multavit. -- S'),
(23, 14, 16, 2, 27, 'Liber cum et mortem contemnit.'),
(24, 48, 81, 1, 81, 'Invidi, difficiles, lucifugi, maledici, monstruosi, alii autem etiam amatoriis levitatibus dediti, alii petulantes, alii.'),
(25, 87, 44, 1, 53, 'Autem voluptates et dolores nasci fatemur e corporis voluptatibus et doloribus -- itaque concedo, quod modo dicebas, cadere causa, si qui incurrunt, numquam vim tantam habent, ut non.'),
(26, 4, 49, 2, 95, 'Utinam esset ille Persius, Scipio vero et Rutilius multo etiam magis, quod, cuius in mente consedit, hoc ipso, quod adest, turbulenta est; si vero molita quippiam.'),
(27, 19, 48, 2, 69, 'Illum, qui dolorem eum fugiat, quo voluptas nulla pariatur? At vero eos et accusamus et iusto odio dignissimos ducimus, qui blanditiis praesentium voluptatum deleniti atque corrupti, quos dolores et quas molestias excepturi sint, obcaecati cupiditate non.'),
(28, 24, 33, 1, 29, 'Et vacuitate omnis molestiae gaudemus, omne autem id, quo gaudemus, voluptas est, ut omne.'),
(29, 22, 80, 1, 48, 'Sint Epicurei, sunt aliae quoque causae, sed multitudinem haec maxime allicit, quod ita putant dici ab illo, recta et honesta quae sint, ea facere ipsa per se ipsam causam non.'),
(30, 21, 9, 2, 66, '-- quod et posse fieri intellegimus et saepe etiam videmus, et.'),
(31, 42, 67, 2, 92, 'Civitas in seditione beata esse potest nec in malis dolor, non existimant oportere nimium nos.'),
(32, 99, 95, 1, 29, 'Distinguantur ostendit; iudicia rerum dirigentur, numquam ullius oratione victi sententia desistemus. Nisi autem rerum natura duo quaerenda sint, unum, quae materia sit, ex qua quaeque res efficiatur.'),
(33, 96, 75, 1, 40, 'Avocent a philosophia, quam his, qui rebus infinitis modum constituant in reque eo meliore, quo maior sit, mediocritatem desiderent. Sive enim ad sapientiam perveniri potest, non paranda nobis solum ea, sed fruenda etiam sapientia est; sive hoc difficile '),
(34, 65, 71, 2, 53, 'A te ipso id quidem facio provocatus gratissimo mihi libro, quem ad modum temeritas et libido et ignavia semper animum excruciant et semper sollicitant turbulentaeque sunt, sic inprobitas si cuius in animo versatur, numquam sinit eum respirare, numquam ad'),
(35, 69, 56, 1, 59, 'Si minus, animo aequo e vita, cum ea non placeat, tamquam e theatro exeamus. Quibus rebus intellegitur nec intemperantiam propter se esse.'),
(36, 52, 51, 2, 75, 'Tarentinis ait se et alliciat suapte natura, non potest esse dubium, quin id sit summum atque extremum bonorum omnium, beateque vivere nihil aliud sit nisi cum.'),
(37, 73, 4, 1, 26, 'Fugiendis ut rationem sequamur monet. Nec enim satis est iudicare quid faciendum non faciendumve sit, sed stare etiam oportet in.'),
(38, 50, 93, 2, 33, 'Hominum vita vexetur, ob eumque errorem et voluptatibus maximis saepe priventur et durissimis animi doloribus torqueantur, sapientia est adhibenda, quae et a falsis initiis profecta vera esse non possunt, victi et debilitati obiecta specie voluptatis trad'),
(39, 72, 10, 1, 39, 'Laetetur, quid est, cur nostri a nostris non legantur? Quamquam, si plane.'),
(41, 27, 61, 2, 68, 'Iis, quos modo nominavi, cum Attico nostro frequenter audivi, cum miraretur ille quidem utrumque, Phaedrum autem etiam amatoriis.'),
(42, 2, 100, 1, 6, 'Semper occultum. Plerumque improborum facta primo suspicio insequitur, dein sermo atque fama, tum accusator, tum iudex; Multi etiam, ut te consule, ipsi se indicaverunt. Quodsi qui satis sibi contra hominum conscientiam saepti esse et voluptates repudiand'),
(43, 58, 91, 1, 87, 'Praestabiliorem aut magis expetendum possimus dicere? Inesse enim necesse est effici, ut sapiens solum amputata circumcisaque inanitate omni et errore.'),
(44, 81, 53, 2, 70, 'Sponte et per se ipsa allicit nec patientia nec assiduitas nec vigiliae nec ea ipsa, quae ab illo est, tum innumerabiles mundi, qui et oriantur et intereant cotidie. Quae etsi mihi nullo modo nec divelli nec distrahi possint, sic de iustitia iudicandum es'),
(45, 9, 97, 1, 72, 'Saepe etiam legum iudiciorumque poenis obligantur. Qui autem alia malunt scribi a nobis, aequi esse debent, quod et acutum genus est et ad corpus nihil referatur, ista.'),
(46, 38, 98, 2, 24, 'Dicit perpauca mutans, sed ita, ut ea, quae dixi, sole ipso illustriora et clariora sunt, si omnia deorsus e regione ferrentur et, ut dixi, ad lineam, hunc naturalem esse omnium corporum motum. Deinde ibidem homo acutus, cum illud ocurreret, si omnia deor'),
(47, 78, 54, 2, 1, 'Nobis ducem praebeat ad voluptatem. Sapientia enim est una, quae maestitiam pellat ex animis, quae nos a libidinum impetu et a spe pariendarum voluptatum seiungi non potest. Atque ut odia, invidiae, despicationes adversantur.'),
(48, 51, 31, 1, 41, 'Ut ipsi auctori huius disciplinae placet: constituam, quid et quale sit id, de quo Lucilius: \'ferreum scriptorem\', verum, opinor, scriptorem tamen, ut legendus sit. Rudem enim esse censet, quantus videtur, vel paulo aut maiorem aut minorem. Ita, quae muta'),
(49, 89, 85, 2, 71, 'Loco videtur quibusdam stabilitas amicitiae vacillare, tuentur tamen eum locum seque facile.'),
(50, 76, 24, 1, 35, 'Debitis aut rerum necessitatibus saepe eveniet, ut et voluptates repudiandae sint et molestiae non.'),
(51, 15, 32, 2, 24, 'Suscepi veritus ne movere hominum studia viderer, retinere non posse. Qui autem, si maxime hoc placeat, moderatius tamen id confidet fore semper occultum. Plerumque improborum facta primo suspicio.'),
(52, 79, 15, 1, 5, 'Quae fugiamus refert omnia. Quod quamquam Aristippi est a Cyrenaicisque melius liberiusque defenditur, tamen eius modi tempora incidunt, ut labore et dolore magnam aliquam quaerat voluptatem. Ut enim aeque doleamus animo, cum corpore dolemus, fieri tamen '),
(53, 70, 74, 2, 73, 'Desideraret.\' -- Ita credo. -- \'Non est igitur voluptas bonum.\' Hoc ne statuam quidem dicturam pater aiebat, si loqui posset. Conclusum est enim aut utilior aut ad miseram vitam afferre momenti quam.'),
(54, 39, 17, 1, 84, 'Torquem illum hosti detraxisse, ut aliquam ex eo.'),
(55, 59, 99, 1, 93, 'Illustriora et clariora sunt, si omnia dixi hausta e fonte naturae.'),
(56, 37, 90, 2, 43, 'Benivole collegisti, nec me tamen laudandis maioribus meis corrupisti nec segniorem ad respondendum reddidisti. Quorum facta quem ad.'),
(57, 63, 42, 1, 20, '-- At magnum periculum adiit. -- In oculis quidem exercitus. -- Quid ex eo perciperet corpore.'),
(58, 41, 69, 2, 19, 'Satis sibi contra hominum conscientiam saepti esse et voluptates et dolores nasci fatemur e corporis voluptatibus et doloribus -- itaque concedo, quod modo dicebas, cadere causa, si qui e nostris aliter existimant, quos quidem video minime.'),
(59, 91, 96, 2, 11, 'Dolor afferat, eorum tamen utrumque et ortum esse e corpore et ad tranquillitatem ferant, quid est cur dubitemus.'),
(60, 33, 5, 1, 35, 'Eas aut laudabilis aut expetendas arbitraretur? Ut enim medicorum scientiam non ipsius artis, sed bonae valetudinis causa probamus, et gubernatoris ars, quia bene navigandi rationem habet, utilitate, non.'),
(61, 80, 18, 2, 8, 'Oratione victi sententia desistemus. Nisi autem rerum natura perspecta erit, nullo modo poterimus sensuum iudicia defendere. Quicquid porro.'),
(62, 35, 72, 1, 22, 'Fecisse aut in poetis evolvendis, ut ego et Triarius te hortatore facimus, consumeret, in quibus sequitur Democritum, non fere labitur. Quamquam utriusque cum multa non probo, inquam.'),
(63, 8, 46, 1, 80, 'Iniuria. Itaque ne iustitiam quidem recte quis dixerit per se esse expetendam et dolorem ipsum per se esse fugiendum. Itaque aiunt hanc quasi naturalem atque insitam in animis inclusae inter se dissident atque discordant, ex quo efficeretur mundus omnesqu'),
(64, 30, 79, 2, 31, 'Quo enim maxime consuevit iactare vestra se.'),
(65, 53, 94, 2, 59, 'Texit, ne interiret. -- At magnum periculum adiit. -- In oculis quidem exercitus. -- Quid ex eo perciperet corpore voluptatem, aut cum Latinis tertio consulatu conflixisse apud Veserim propter voluptatem; quod vero.'),
(66, 45, 35, 1, 1, 'Habet; inanium autem cupiditatum nec modus ullus nec finis inveniri potest. Quodsi vitam omnem perturbari videmus errore et inscientia, sapientiamque.'),
(67, 12, 57, 2, 32, 'Aut inpotenti iniuste facta conducunt, qui nec facile.'),
(68, 25, 22, 1, 26, 'Privatio recte nominata est voluptas. Ut enim, cum cibo et potione fames sitisque depulsa est, ipsa detractio molestiae consecutionem affert voluptatis, sic in omni re doloris amotio successionem efficit voluptatis. Itaque non.'),
(69, 36, 45, 1, 45, 'Magnitudinem celeritas, diuturnitatem allevatio consoletur. Ad ea cum accedit, ut neque divinum numen horreat nec praeteritas voluptates effluere patiatur earumque assidua recordatione laetetur, quid est, cur nostri a nostris non legantur? Quamquam, si pl'),
(70, 29, 43, 2, 25, 'Est, quid aut ad beatam aut ad bene vivendum aptior partitio quam illa, qua est usus Epicurus? Qui unum genus posuit earum cupiditatum, quae essent et naturales et necessariae, alterum.'),
(71, 56, 21, 2, 14, 'Quos dolores et quas molestias.'),
(72, 64, 63, 1, 21, 'Iudicium et nostrum scribendi ordinem adiungimus, quid habent, cur Graeca anteponant iis, quae recordamur. Stulti autem malorum memoria torquentur, sapientes bona praeterita grata recordatione renovata delectant. Est autem situm in.'),
(73, 94, 23, 1, 78, 'Rebus infinitis modum constituant in reque eo meliore, quo maior sit, mediocritatem desiderent. Sive enim ad sapientiam perveniri potest, non paranda nobis solum ea, sed fruenda etiam sapientia est; sive hoc difficile est, tamen nec modus ullus nec finis '),
(74, 100, 40, 2, 37, 'Angusta, quam magnos quantaque amoris conspiratione consentientis tenuit amicorum greges! Quod fit etiam nunc ab Epicureis. Sed ad haec, nisi molestum est, habeo quae velim. An.'),
(75, 13, 55, 1, 3, 'Altera occulta quaedam et quasi architecto beatae vitae deduceret? Qui quod tibi parum videtur.'),
(76, 49, 88, 2, 9, 'Bonum sit aut quid iudicat, quo aut petat aut fugiat aliquid, praeter voluptatem et dolorem? Sunt autem quidam e nostris, qui haec subtilius velint tradere et.'),
(77, 34, 2, 1, 27, 'Esset et virtus et cognitio rerum, quod minime ille vult expetenda. Haec igitur Epicuri non probo, tum illud in primis, quod, cum in rerum.'),
(78, 84, 65, 2, 4, 'Videtur multis voluptatibus, cum ipsi naturae patrioque amori praetulerit ius maiestatis atque imperii. Quid? T. Torquatus, is qui consul cum Cn. Octavio fuit, cum.'),
(79, 23, 84, 2, 93, 'Me ad alias litteras vocent, genus hoc scribendi, etsi sit elegans, personae.'),
(80, 74, 64, 1, 80, 'Non arte laudatur, sic sapientia, quae ars vivendi putanda est, non expeteretur, si nihil tale metuamus. Iam illud quidem physici, credere aliquid esse minimum, quod profecto numquam putavisset, si a Polyaeno, familiari suo, geometrica discere maluisset q'),
(81, 61, 34, 1, 91, 'Se ipsum, quosque labores propter suam voluptatem susciperet, eosdem suscipiet propter amici voluptatem. Quaeque de virtutibus dicta sunt, explicabo. Nemo enim ipsam voluptatem, quia.'),
(82, 17, 58, 2, 50, 'Una virtute ponunt et splendore nominis capti quid natura desideret. Tum vero, si stabilem scientiam rerum tenebimus, servata illa, quae quasi delapsa de caelo est ad cognitionem omnium, regula, ad quam omnia iudicia rerum in sensibus.'),
(83, 28, 28, 2, 28, 'Praetore salutatus Athenis Albucius. Quem quidem locum comit multa venustate et omni sale idem Lucilius, apud quem praeclare Scaevola: Graecum te, Albuci, quam Romanum atque Sabinum, municipem Ponti, Tritani, centurionum, praeclarorum hominum ac primorum '),
(84, 31, 86, 1, 53, 'Eum Torquatum, qui hoc primus cognomen invenerit, aut torquem illum hosti detraxisse, ut aliquam ex eo credo quibusdam usu venire; ut abhorreant a Latinis, quod inciderint in inculta quaedam et quasi involuta aperiri.'),
(85, 71, 60, 1, 85, 'Corporis voluptatibus, videtisne quam nihil praetermittatur quod vitam adiuvet, quo facilius id, quod his libris quaeritur, qui sit finis, quid extremum, quid ultimum, quo sint omnia bene vivendi recteque faciendi consilia referenda, quid sequatur natura '),
(86, 92, 36, 2, 31, 'Albucius, hinc inimicus. Sed iure Mucius. Ego autem mirari satis non queo unde hoc sit tam insolens domesticarum rerum fastidium. Non est omnino hic.'),
(87, 43, 89, 1, 23, 'Vel fortunae vel ingenii liberalitati magis conveniunt, qua qui utuntur, benivolentiam sibi conciliant et, quod aptissimum.'),
(88, 60, 19, 2, 52, 'Voluptate aegritudinem statim consequi, nisi in voluptatis locum dolor forte successerit, at contra gaudere nosmet omittendis doloribus, etiamsi voluptas ea, quae sensum moveat, nulla successerit, eoque intellegi potest quanta voluptas.'),
(89, 85, 14, 2, 44, 'Laudatur, sic sapientia, quae ars vivendi putanda est, non satis politus iis artibus, quas qui tenent, eruditi appellantur -- aut ne deterruisset alios a studiis. Quamquam te quidem video minime esse deterritum. Quae cum dixisset, Explicavi.'),
(90, 3, 41, 1, 83, 'Et iudicio ab eadem illa constituto veri a falso distinctio traditur. Restat locus huic disputationi vel maxime necessarius de amicitia.'),
(91, 11, 50, 2, 66, 'Ad me accedis, saluto: \'chaere,\' inquam, \'Tite!\' lictores, turma omnis chorusque: \'chaere, Tite!\' hinc hostis mi Albucius, hinc inimicus. Sed iure Mucius. Ego autem.'),
(92, 93, 83, 1, 61, 'Vel plurimum afferat. Nam diligi et carum esse iucundum est propterea, quia tutiorem vitam et voluptatem pleniorem efficit. Itaque non ob ea solum incommoda, quae eveniunt inprobis, fugiendam.'),
(93, 75, 13, 1, 87, 'Locus; sed ita sentio et saepe etiam legum iudiciorumque poenis obligantur. Qui autem ita frui volunt voluptatibus, ut nulli propter eas consequantur dolores, et qui suum iudicium retinent, ne voluptate victi faciant id, quod sentiant non esse faciendum, '),
(94, 62, 30, 2, 20, 'Existimant oportere nimium nos causae confidere, sed et argumentandum et accurate disserendum.'),
(95, 44, 25, 1, 96, 'Responsum est eo libro, quo a populo Romano locatus sum, debeo profecto, quantumcumque possum, in.'),
(96, 26, 37, 2, 32, 'Neque enim tempus est ullum, quo non plus habeat sapiens, quod gaudeat, quam quod angatur. Optime vero Epicurus, quod exiguam dixit fortunam intervenire sapienti maximasque ab eo delectari, quod ista Platonis, Aristoteli, Theophrasti orationis ornamenta n'),
(97, 83, 76, 1, 78, 'Appetendi et refugiendi et omnino rerum gerendarum initia proficiscuntur aut a dolore. Quod cum ita sit, perspicuum est nihil desiderare manum, cum ita esset affecta, secundum non recte, si voluptas summum sit bonum, affirmatis nullam omnino fore. De qua '),
(98, 32, 29, 2, 30, 'Praeter voluptatem et dolorem? Sunt autem quidam Epicurei timidiores paulo contra vestra convicia, sed tamen satis acuti, qui verentur ne, si amicitiam propter nostram voluptatem expetendam putemus, tota.'),
(99, 67, 1, 1, 82, 'Extremum malorum? Qua de re cum sit inter doctissimos summa dissensio.'),
(100, 57, 66, 2, 81, 'Si loqui posset. Conclusum est enim.');
INSERT INTO `medio_de_pago` (`id_medio_pago`, `medio_de_pago`) VALUES
(1, 'Tarjeta de Crédito'),
(2, 'Tarjeta de Débito'),
(3, 'Transferencia Bancaria'),
(4, 'Efectivo'),
(5, 'PayPal'),
(6, 'Criptomoneda'),
(7, 'Cheque'),
(8, 'Pago Móvil');
INSERT INTO `orden_de_compra` (`id_orden`, `fecha_orden`, `id_cliente`, `id_tipo`, `monto_total`, `id_medio_pago`, `id_envio`, `descripcion`) VALUES
(2, '2024-06-27', 10, 2, 7703.59, 8, 68, 'Homero Ennius, Afranius a Menandro solet. Nec vero, ut noster Lucilius, recusabo, quo minus animus a se ipse dissidens secumque discordans gustare partem ullam liquidae voluptatis et liberae potest. Atqui pugnantibus et contrariis studiis consiliisque sem'),
(3, '2024-10-04', 96, 1, 7134.37, 7, 22, 'Bello animadversionis metu contineret, saluti prospexit civium, qua intellegebat contineri suam. Atque haec.'),
(4, '2024-09-01', 39, 2, 18162.91, 3, 53, 'Ultimum vel extremum -- quod Graeci telos nominant --, quod ipsum nullam ad aliam rem, ad id autem res referuntur omnes, fatendum est summum.'),
(5, '2024-09-18', 73, 2, 13361.57, 1, 90, 'Summum erat in utroque studium, deinde Torquatus: Quoniam nacti te, inquit.'),
(6, '2024-11-13', 100, 1, 12813.45, 2, 61, 'Patrius, cum idem fabellas Latinas ad verbum e.'),
(7, '2024-11-10', 43, 2, 17710.00, 5, 4, 'Iudicia defendere. Quicquid porro animo cernimus, id.'),
(8, '2024-04-06', 22, 1, 14125.36, 4, 69, 'Est tam invidus, qui ab eo nos abducat? Sin laboramus, quis est, qui Ennii Medeam aut Antiopam Pacuvii spernat aut reiciat, quod se isdem Euripidis fabulis delectari dicat, Latinas litteras.'),
(9, '2024-12-28', 34, 1, 16892.80, 5, 79, 'Voluptas animi et corporis voluptatibus, videtisne quam nihil molestiae consequatur, vel illum, qui dolorem ipsum, quia dolor sit, amet, consectetur, adipisci velit, sed quia iucunditatis vel plurimum afferat. Nam diligi et carum esse.'),
(10, '2024-05-17', 8, 2, 14455.53, 1, 57, 'Et terminatas habet; inanium autem cupiditatum nec modus est neque honoris neque imperii nec libidinum nec.'),
(11, '2024-06-21', 19, 1, 4812.11, 7, 40, 'Dicere, -- et illum motum naturalem omnium ponderum, ut ipse.'),
(12, '2024-06-03', 86, 2, 15643.62, 2, 80, 'Tam id reprehendunt, si remissius agatur, sed tantum studium tamque multam operam ponendam in eo non arbitrantur. Erunt etiam, et ii quidem eruditi Graecis litteris, contemnentes Latinas, qui se Latina scripta dicunt contemnere. In quibus sequitur Democri'),
(13, '2024-05-28', 52, 2, 14505.40, 6, 52, 'Veritus ne movere hominum studia viderer, retinere non posse. Qui autem, si maxime hoc placeat, moderatius tamen id confidet fore semper occultum. Plerumque improborum facta primo suspicio insequitur, dein sermo atque fama.'),
(14, '2024-05-13', 97, 1, 16742.19, 4, 62, 'Circumcisaque inanitate omni et errore naturae finibus contentus sine aegritudine.'),
(15, '2024-08-27', 87, 2, 12773.50, 8, 2, 'Atque servare id, quod maxime placeat, facere possimus, omnis voluptas assumenda est, omnis dolor repellendus. Temporibus.'),
(16, '2024-05-13', 70, 1, 11935.29, 3, 3, 'Ut noster Lucilius, recusabo, quo minus omnes mea.'),
(17, '2024-10-11', 92, 2, 16829.35, 6, 28, 'Legendum his esse potiora. Quid est cur tam multi sint Epicurei, sunt aliae quoque.'),
(18, '2025-01-08', 16, 1, 16025.55, 7, 10, 'Est, qui dolorem ipsum, quia dolor sit, amet, consectetur, adipisci velit, sed quia iucunditatis vel plurimum afferat. Nam diligi et carum esse iucundum est propterea, quia tutiorem vitam et voluptatem pleniorem efficit. Itaque non ob ea solum incommoda, '),
(19, '2024-05-21', 94, 1, 17611.03, 3, 24, 'Inter dolorem et voluptatem; illud enim ipsum, quod quibusdam medium videretur, cum omni dolore careret, non modo numquam.'),
(20, '2024-02-22', 65, 2, 15246.20, 8, 49, 'Tam expetendas, quam nostras expeteremus, quo loco videtur quibusdam stabilitas amicitiae vacillare, tuentur tamen eum locum seque facile, ut mihi.'),
(21, '2024-12-20', 1, 1, 3846.86, 2, 38, 'Laudantium, totam rem aperiam eaque ipsa, quae ab illo est.'),
(22, '2024-06-06', 4, 2, 8516.63, 5, 42, 'Dicunt contemnere. In quibus hoc primum est in quo a populo Romano locatus.'),
(23, '2024-11-16', 32, 2, 17811.36, 1, 93, 'In voluptate ponatur, sed sine hoc institutionem omnino amicitiae non modo non inopem, ut vulgo putarent, sed locupletiorem etiam esse quam vacare omni dolore et molestia perfruique maximis et animi et molestiam dolor afferat, eorum tamen utrumque et ortu'),
(24, '2024-06-22', 44, 1, 6509.05, 4, 58, 'Dixi hausta e fonte naturae, si tota oratio nostra omnem sibi fidem sensibus confirmat, id est voluptatem et parvam et non necessariam et quae sequamur et quae fugiamus refert omnia. Quod quamquam Aristippi est a Chrysippo praetermissum in Stoicis? Legimu'),
(25, '2024-12-14', 27, 1, 8902.01, 4, 41, 'Occaecat cupidatat non proident, sunt in culpa.'),
(26, '2024-07-18', 60, 2, 2460.39, 3, 86, 'Assumenda est, omnis dolor repellendus. Temporibus autem quibusdam et aut officiis debitis aut rerum necessitatibus saepe eveniet, ut et voluptates et dolores animi quam corporis. Nam corpore nihil nisi praesens et quod adest sentire possumus, animo autem'),
(27, '2024-11-09', 67, 1, 12591.59, 8, 17, 'Ignavi, numquam in sententia permanentes, quas.'),
(28, '2024-06-23', 23, 2, 14492.47, 5, 84, 'Bestiae paene loquuntur magistra ac duce natura nihil esse prosperum nisi voluptatem, nihil asperum.'),
(29, '2024-10-20', 45, 1, 6785.49, 7, 64, 'E patre audiebam facete et urbane Stoicos irridente, statua est in eo, qui ita sit affectus, eum necesse est in.'),
(30, '2024-08-04', 83, 2, 13375.32, 2, 31, 'Ne interiret. -- At magnum periculum adiit. -- In oculis quidem exercitus. -- Quid ex.'),
(31, '2024-03-11', 51, 1, 6933.46, 6, 83, 'Nisi mihi Phaedrum, inquam, tu mentitum aut Zenonem putas, quorum utrumque audivi, cum miraretur ille.'),
(32, '2024-03-12', 11, 2, 18691.27, 1, 33, 'In nostris poetis aut inertissimae segnitiae est aut in liberos atque in sanguinem suum tam crudelis fuisse, nihil ut de omni virtute sit dictum.'),
(33, '2024-07-30', 48, 1, 3103.13, 1, 78, 'Diogenem, Antipatrum, Mnesarchum, Panaetium, multos alios in primisque familiarem nostrum Posidonium. Quid?'),
(34, '2024-06-26', 15, 2, 16083.42, 7, 76, 'Non paranda nobis solum ea, sed fruenda etiam sapientia est.'),
(35, '2025-02-03', 38, 1, 471.43, 4, 72, 'Manum, cum ita sit, perspicuum est nihil desiderare manum, cum ita sit, perspicuum est omnis rectas res atque laudabilis eo referri, ut cum voluptate conectitur. Nam et praeterita grate meminit et praesentibus ita potitur, ut animadvertat quanta sint ea q'),
(36, '2024-12-31', 78, 2, 15358.39, 3, 48, 'Latinas ad verbum e Graecis expressas non inviti legant. Quis enim tam inimicus paene nomini.'),
(37, '2024-10-09', 42, 1, 10294.90, 6, 71, 'Erit hoc quasi, provincias atomis dare, quae recte, quae oblique ferantur, deinde eadem illa atomorum.'),
(38, '2024-02-28', 28, 2, 12639.13, 8, 81, 'Incurrunt, saepe etiam videmus, et perspicuum est omnis rectas res atque laudabilis eo referri, ut cum voluptate vivere. Huic certae stabilique sententiae quae sint coniuncta explicabo brevi. Nullus in ipsis error est finibus.'),
(39, '2024-08-29', 18, 2, 6230.43, 2, 97, 'Senectutem esse discenda. Quae cum tota res (est) ficta pueriliter, tum ne efficit quidem, quod vult. Nam et ipsa declinatio ad libidinem fingitur -- ait enim declinare.'),
(40, '2024-10-14', 21, 1, 4850.84, 5, 11, 'Ante tractatos? Quid? Epicurei num desistunt de isdem, de quibus et ab antiquis, ad arbitrium suum scribere? Quodsi Graeci leguntur a.'),
(41, '2024-11-28', 3, 2, 129.34, 3, 94, 'Crudeli; sin, ut dolore suo sanciret militaris imperii disciplinam exercitumque in gravissimo bello animadversionis metu contineret, saluti prospexit civium, qua intellegebat contineri suam. Atque.'),
(42, '2024-07-27', 63, 1, 14156.81, 5, 35, 'Cuiquam, sed contra semper afficit cum vi sua atque natura, quod tranquillat animos, tum spe nihil earum rerum defuturum, quas.'),
(43, '2024-02-25', 80, 2, 2641.53, 1, 29, 'Quod angatur. Optime vero Epicurus, quod exiguam dixit fortunam intervenire.'),
(44, '2025-01-31', 85, 1, 16762.41, 7, 7, 'Voluptate, a meque ei responsum, cum C. Triarius, in primis gravis et doctus adolescens, ei disputationi interesset. Nam cum ad me accedis, saluto: \'chaere,\' inquam, \'Tite!\' lictores, turma.'),
(45, '2024-06-02', 98, 1, 148.30, 2, 23, 'Quod sentiant non esse faciendum, ii voluptatem maximam adipiscuntur praetermittenda voluptate. Idem etiam dolorem saepe perpetiuntur, ne, si id non faciant.'),
(46, '2025-01-16', 46, 2, 2945.39, 6, 51, 'Non impediri rationem amicitiae, si summum bonum esse vult, summumque malum dolorem, idque instituit docere sic: Omne animal, simul atque natum sit.'),
(47, '2024-06-24', 84, 1, 8909.56, 4, 99, 'Perpetuam iucunditatem vitae tenere possumus neque vero ipsam amicitiam tueri, nisi aeque amicos et nosmet ipsos diligamus, idcirco et hoc ipsum efficitur in amicitia, et amicitia cum voluptate vivere. Nec enim satis est iudicare quid faciendum non facien'),
(48, '2024-05-29', 36, 2, 18754.25, 8, 70, 'Fore ut atomus altera alteram posset attingere itaque ** attulit rem commenticiam: declinare dixit atomum perpaulum, quo nihil nec summum nec infimum nec medium nec ultimum nec extremum sit, ita ferri, ut concursionibus inter se cohaerescant, ex quo effic'),
(49, '2024-07-05', 68, 1, 11652.39, 4, 1, 'Cognoscerem, quoniam mihi ea facultas, ut id meo arbitratu facerem.'),
(50, '2025-01-03', 35, 2, 14059.43, 8, 60, 'Laetitiam nobis voluptas animi et molestiam dolor afferat, eorum tamen utrumque et ortum esse e corpore et ad dolores ita paratus est, ut meminerit maximos morte.'),
(51, '2024-09-04', 74, 2, 12220.85, 3, 12, 'Sed ii indocti, qui, quae pueros non didicisse turpe est, ea putant usque ad senectutem esse discenda. Quae cum tota res (est) ficta pueriliter, tum ne efficit.'),
(52, '2024-08-31', 88, 1, 5700.42, 5, 5, 'Plena sit, ratio ipsa monet amicitias comparare, quibus partis confirmatur animus et a falsis initiis profecta vera esse.'),
(53, '2024-04-04', 9, 2, 11084.87, 1, 34, 'Cum omnino nulla sit utilitas ex amicitia, tamen ipsi amici propter se expetendam esse dicemus, sed quia pacem animis afferat et eos quasi concordia quadam placet ac leniat.'),
(54, '2024-05-30', 58, 1, 3057.57, 7, 75, 'Iste vester plane, ut mihi videtur, expediunt. Ut enim mortis metu omnis quietae vitae status perturbatur, et ut succumbere doloribus eosque humili animo inbecilloque ferre miserum est, ob eamque debilitatem animi multi parentes.'),
(55, '2024-11-20', 13, 1, 11107.45, 2, 73, 'Primos congressus copulationesque et consuetudinum instituendarum voluntates fieri propter voluptatem; quod vero securi percussit filium, privavisse se etiam videtur multis.'),
(56, '2024-05-17', 26, 2, 1071.14, 6, 44, 'Quondam a L. Torquato, homine omni doctrina erudito, defensa est Epicuri sententia de voluptate, a meque ei responsum, cum C. Triarius, in primis gravis et doctus adolescens, ei disputationi interesset. Nam cum ad te ne Graecis quidem cedentem in philosop'),
(57, '2024-07-17', 64, 1, 12537.31, 6, 19, 'Ut plura nemini e nostris, et scribentur fortasse plura, si vita suppetet; et tamen, qui diligenter haec, quae vitam omnem continent, neglegentur? Nam, ut sint opera, studio, labore meo doctiores cives mei, nec cum iracundia aut pertinacia recte disputari'),
(58, '2024-08-19', 33, 2, 8078.88, 4, 6, 'Honesta quae sint, ea facere.'),
(59, '2024-06-07', 12, 1, 18173.56, 8, 65, 'Quam continens, quam severa sit. Non enim hanc solam sequimur, quae suavitate aliqua naturam ipsam movet et cum iucunditate quadam percipitur sensibus, sed maximam voluptatem illam habemus, quae percipitur omni dolore et molestia perfruique maximis et.'),
(60, '2024-10-26', 89, 2, 2094.13, 3, 91, 'Igitur modis video esse multos, sed imperitos --, quamquam autem et laetitiam nobis voluptas animi et molestiam dolor afferat, eorum tamen utrumque et ortum esse e corpore et ad corpus nihil referatur, ista sua sponte et per se esset et virtus et.'),
(61, '2024-09-30', 95, 1, 17571.01, 5, 67, 'Iudicat, quo aut petat aut fugiat aliquid, praeter voluptatem et parvam et non necessariam et quae sequamur et quae fugiamus refert omnia. Quod quamquam Aristippi est a Cyrenaicisque melius liberiusque.'),
(62, '2025-02-04', 30, 2, 8232.19, 1, 45, 'Esse bonorum eum voluptate vivere. Nec enim satis est iudicare quid faciendum non faciendumve sit, sed stare etiam oportet in eo, quod sit a dolore corporis praesenti futurove seiunctum. Nec vero quisquam stultus non horum morborum aliquo laborat, nemo ig'),
(63, '2024-08-28', 77, 1, 12503.98, 7, 59, 'Civitatis, P. Scaevolam M\'.que Manilium.'),
(64, '2025-02-11', 31, 2, 2706.96, 2, 54, 'Enim mortis metu omnis quietae vitae status perturbatur, et ut succumbere doloribus eosque humili animo inbecilloque ferre miserum est, ob eamque debilitatem animi multi parentes, multi amicos, non nulli patriam, plerique autem se ipsos amentur. Etenim si'),
(65, '2024-11-22', 14, 1, 11621.87, 3, 47, 'Et terroribus cupiditatibusque detractis et omnium falsarum opinionum temeritate derepta certissimam se nobis ducem praebeat ad voluptatem. Sapientia.'),
(66, '2024-08-25', 69, 2, 6732.32, 6, 82, 'Opinionum temeritate derepta certissimam se nobis ducem praebeat ad voluptatem. Sapientia enim est una, quae maestitiam pellat ex animis, quae nos vocet ad se et Consentinis et Siculis scribere. Facete is quidem, sicut.'),
(67, '2024-07-13', 57, 1, 1561.25, 5, 96, 'Sic verterem Platonem aut Aristotelem, ut verterunt nostri poetae fabulas, male, credo.'),
(68, '2024-07-11', 47, 2, 13733.84, 7, 14, 'Tam amicis quam sibi, quibus non solum praesentibus fruuntur, sed etiam effectrices sunt voluptatum tam amicis quam sibi, quibus non solum praesentibus fruuntur, sed.'),
(69, '2024-04-09', 29, 1, 940.06, 4, 13, 'Ad minuendas vitae molestias accessio potest fieri, quanta ad augendas, cum conscientia factorum, tum poena legum odioque civium? Et tamen in quibusdam neque pecuniae modus est ullus investigandi veri, nisi inveneris, et quaerendi defatigatio turpis est.'),
(70, '2024-03-31', 66, 2, 3264.00, 2, 66, 'Vult \'fodere aut arare aut aliquid ferre denique\' -- non enim illum ab industria, sed ab inliberali labore deterret .'),
(71, '2025-01-31', 71, 2, 5407.34, 8, 18, 'Tempus aut in armatum hostem impetum fecisse aut in liberos atque in sanguinem suum tam crudelis fuisse, nihil ut de utilitatibus, nihil ut de.'),
(72, '2024-10-03', 7, 1, 17810.66, 1, 26, 'Excelsus omni est liber cura et angore, cum et tibi probatus videretur et iis, quos ego posse iudicare arbitrarer, plura suscepi veritus ne movere hominum studia viderer.'),
(73, '2024-10-23', 75, 1, 2893.25, 1, 21, 'Amicorum greges! Quod fit etiam nunc ab Epicureis.'),
(74, '2024-12-09', 40, 2, 14365.90, 4, 74, 'Totus est alienus. Democritea dicit perpauca mutans, sed ita, ut ea, quae sensum moveat, nulla successerit, eoque intellegi potest quanta voluptas sit non dolere. Sed ut iis.'),
(75, '2024-10-05', 50, 1, 10020.42, 2, 39, 'Leviora, ut urbanitas summa appareat, doctrina mediocris. Ego autem quem timeam lectorem, cum ad me accedis, saluto: \'chaere,\' inquam, \'Tite.'),
(76, '2024-10-24', 62, 2, 2345.13, 6, 98, 'Autem ita frui volunt voluptatibus, ut nulli propter eas consequantur dolores, et qui.'),
(77, '2024-03-09', 99, 2, 807.74, 5, 16, 'Ei disputationi interesset. Nam cum ad me in Cumanum salutandi causa uterque venisset, pauca primo.'),
(78, '2024-04-10', 25, 1, 8014.72, 8, 37, 'Naturales nec necessariae. Quarum ea ratio est, ut omne.'),
(79, '2024-09-18', 54, 1, 16691.89, 7, 88, 'Qui est imbutus quietus esse numquam potest. Praeterea bona praeterita non meminerunt, praesentibus non fruuntur, futura modo expectant, quae quia.'),
(80, '2024-12-25', 82, 2, 18444.71, 3, 63, 'Enim maxime consuevit iactare vestra se oratio, tua praesertim, qui studiose antiqua persequeris, claris et fortibus viris commemorandis eorumque factis non emolumento.'),
(81, '2024-07-14', 61, 1, 17898.57, 8, 89, 'Quo enim maxime consuevit iactare vestra se oratio.'),
(82, '2024-02-26', 55, 2, 14758.87, 4, 32, 'Quae maestitiam pellat ex animis, quae nos exhorrescere metu non sinat. Qua praeceptrice in tranquillitate vivi potest omnium cupiditatum ardore.'),
(83, '2025-01-06', 59, 1, 13815.47, 3, 43, 'Earum rerum hic tenetur a sapiente delectus, ut aut voluptates omittantur maiorum voluptatum adipiscendarum causa aut dolores suscipiantur maiorum dolorum effugiendorum gratia. Sed de clarorum hominum factis illustribus et gloriosis satis hoc loco dictum '),
(84, '2024-08-19', 91, 2, 1077.82, 5, 9, 'In voluptatis locum dolor forte successerit, at contra gaudere nosmet omittendis doloribus, etiamsi voluptas ea, quae corrigere vult, mihi quidem videtur. Ac.'),
(85, '2024-08-30', 79, 1, 15283.44, 7, 8, 'Aequitatem, fidem, neque homini infanti aut inpotenti iniuste facta conducunt, qui nec facile efficere possit, quod melius sit.'),
(86, '2024-09-15', 24, 2, 16132.07, 1, 30, 'Labefactant saepe rem publicam. Ex cupiditatibus odia, discidia, discordiae, seditiones, bella nascuntur.'),
(87, '2024-09-21', 41, 2, 13553.42, 2, 20, 'Sed ista sequimur, ut sine cura metuque vivamus animumque et corpus, quantum efficere possimus, molestia liberemus. Ut enim ad minima veniam, quis nostrum exercitationem.'),
(88, '2024-04-29', 20, 1, 13799.96, 6, 50, 'Est ullus investigandi veri, nisi inveneris, et quaerendi defatigatio turpis est, cum esset accusata et vituperata ab Hortensio.'),
(89, '2025-01-11', 6, 2, 14597.03, 6, 95, 'Solum praesentibus fruuntur, sed etiam quid a singulis philosophiae disciplinis diceretur, persecuti sumus. Ut autem a facillimis ordiamur, prima veniat in medium Epicuri ratio, quae plerisque notissima est. Quam a nobis philosophia defensa et collaudata '),
(90, '2024-10-11', 17, 1, 11969.79, 4, 85, 'Deinde ibidem homo acutus, cum illud ocurreret, si omnia deorsus e regione inferiorem locum petentium.'),
(91, '2024-05-04', 76, 2, 5198.19, 3, 87, 'Gloriosis satis hoc loco dictum sit. Erit enim iam de omnium virtutum cursu ad voluptatem proprius disserendi locus. Nunc autem explicabo, voluptas ipsa quae.'),
(92, '2024-03-25', 2, 1, 14902.44, 5, 36, 'De rebus alia ratione compositis, quid est, cur nostri a nostris de amicitia dicenda sunt. Praeclare enim Epicurus his paene verbis: \'Eadem\', inquit, \'scientia confirmavit animum, ne quod aut sempiternum aut diuturnum timeret malum, quae perspexit in hoc '),
(93, '2024-11-20', 72, 2, 14007.28, 8, 56, 'Ego autem quem timeam lectorem, cum ad me in Cumanum salutandi causa uterque venisset, pauca primo inter nos ea, quae corrigere vult, mihi quidem.'),
(94, '2024-08-13', 37, 1, 14426.55, 7, 92, 'Bestiae paene loquuntur magistra ac duce.'),
(95, '2025-01-04', 49, 1, 14419.76, 2, 100, 'Miseram vitam afferre momenti quam eorum utrumvis, si aeque diu sit in corpore. Non placet autem detracta voluptate aegritudinem statim consequi, nisi in voluptatis locum dolor forte successerit, at contra gaudere nosmet omittendis doloribus, etiamsi volu'),
(96, '2024-11-11', 53, 2, 10736.39, 1, 46, 'Memoriter, tum etiam erga nos amice et benivole collegisti, nec me tamen laudandis maioribus meis corrupisti nec segniorem ad respondendum reddidisti. Quorum facta quem.'),
(97, '2024-06-12', 90, 1, 14730.83, 1, 27, 'Non inopem, ut vulgo putarent, sed locupletiorem etiam esse quam Graecam. Quando enim nobis, vel dicam aut oratoribus bonis aut.'),
(98, '2024-04-14', 56, 2, 628.25, 7, 15, 'Quieti videre, nihil tranquilli potest. Quodsi vitam omnem perturbari videmus errore et inscientia, sapientiamque esse solam, quae nos vocet ad se et alliciat suapte.'),
(99, '2024-06-30', 5, 1, 13732.88, 4, 55, 'Accusata et vituperata ab Hortensio. Qui liber cum et mortem contemnit, qua qui affecti sunt in eadem causa sunt, qua ante quam nati, et.'),
(100, '2024-12-17', 81, 2, 1150.52, 3, 25, 'Corpus referri, nec ob eam causam non fuisse. -- Torquem detraxit hosti. -- Et quidem se texit, ne interiret. -- At magnum periculum adiit. -- In oculis quidem exercitus. -- Quid ex eo credo quibusdam usu venire; ut abhorreant a Latinis, quod inciderint i');
